const items = $input.all();
const webhookData = $('Webhook').first().json;
const startTime = Date.now();

const results = items.map(item => {
  // Check for API errors
  if (item.json.errors || item.json.error) {
    const errorMsg = item.json.errors?.[0] || item.json.error?.message || 'Unknown GNews API error';
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: errorMsg,
          status: 'API_ERROR'
        },
        meta: {
          provider: 'gnews',
          execution_mode: webhookData.body.execution_mode || 'online'
        }
      }
    };
  }

  const articles = (item.json.articles || []).map((article, idx) => ({
    id: `gnews-${Date.now()}-${idx}`,
    title: article.title || '',
    description: article.description || '',
    content: article.content || '',
    url: article.url || '',
    image: article.image || null,
    published_at: article.publishedAt || null,
    source: {
      name: article.source?.name || 'Unknown',
      url: article.source?.url || null
    },
    found_in: ['gnews']
  }));

  return {
    json: {
      success: true,
      data: {
        articles: articles,
        meta: {
          query: webhookData.body.query,
          total_results: item.json.totalArticles || articles.length,
          sources_queried: ['gnews'],
          language: webhookData.body.options?.language || 'fr',
          country: webhookData.body.options?.country || 'fr'
        }
      },
      meta: {
        provider: 'gnews',
        execution_mode: webhookData.body.execution_mode || 'online',
        processing_time_ms: Date.now() - startTime
      }
    }
  };
});

return results;
